from itertools import product

from typing import Sequence

def has_zero_sum_subsequence(seq: Sequence[int], m: int) -> bool:
    """Return True iff some non-empty subset of `seq` sums to 0 modulo m.

    Reachable-set dynamic program over the additive group Z/m: `reachable`
    holds all non-empty subset sums seen so far.  Runs in O(len(seq) * m)."""
    reachable: set[int] = set()
    for value in seq:
        v = value % m
        new_reachable = {v}
        for r in reachable:
            new_reachable.add((r + v) % m)
        reachable |= new_reachable
        if 0 in reachable:
            return True
    return 0 in reachable

from itertools import product
from typing import Sequence

def _has_zero_sum(seq: Sequence[int], m: int) -> bool:
    reachable: set[int] = set()
    for value in seq:
        v = value % m
        nxt = {v} | {(r + v) % m for r in reachable}
        reachable |= nxt
        if 0 in reachable:
            return True
    return 0 in reachable

def davenport_constant_cyclic(m: int) -> int:
    """Least n such that every length-n sequence over Z/m has a non-empty
    zero-sum subsequence.  By the Cyclic Davenport Theorem this equals m;
    the routine locates the monotone threshold by increasing n."""
    n = 1
    while True:
        if all(_has_zero_sum(seq, m) for seq in product(range(m), repeat=n)):
            return n
        n += 1

for m in range(1, 7):
    d = davenport_constant_cyclic(m)
    witness = tuple(1 for _ in range(m - 1))
    print(f'm={m}: D(Z/m)={d} (== m: {d == m}); extremal seq {witness}')

