function WeightedKernelCover(n, m, W):
    allowed <- [0] ++ W
    admissible <- [ c in allowed^n : c has some non-zero entry ]
    for x in (Z/m)^n:
        covered <- FALSE
        for c in admissible:
            if (sum_i c_i * x_i) mod m == 0: covered <- TRUE; break
        if not covered: return FALSE
    return TRUE

